                line += val
            print(line)

Grid3(d1_out).print_6s()

# Let me check the 6s in Demo 1 more carefully - what shape do they form?
d1_out = demo_pairs[0]["output"]

print("All 6 positions in Demo 1 output:")
sixes = []
for r in range(14):
    for c in range(21):
        if d1_out[r][c] == 6:
            sixes.append((r, c))
            print(f"  ({r},{c})")

print(f"\nTotal 6s: {len(sixes)}")

# What's the bounding box?
if sixes:
    rows = [r for r, c in sixes]
    cols = [c for r, c in sixes]
    print(f"\nBounding box: rows {min(rows)}-{max(rows)}, cols {min(cols)}-{max(cols)}")
    print(f"  Box size: {max(rows)-min(rows)+1} x {max(cols)-min(cols)+1}")

    # Check if the box is filled in
    print("\nChecking if bounding box is filled with 6s:")
    filled = True
    for r in range(min(rows), max(rows)+1):
        for c in range(min(cols), max(cols)+1):
            if d1_out[r][c] != 6:
                print(f"  (!) Box cell ({r},{c}) is NOT 6 (value={d1_out[r][c]})")
                filled = False
    if filled:
        print("  ✓ Bounding box is COMPLETELY filled with 6s")

